const rl = readline.createInterface({ input: process.stdin, terminal: false });
let lines = [];
rl.on('line', (line) => lines.push(line));
rl.on('close', () => {
    let [a, ta] = lines[0].trim().split(/\s+/).map(Number);
    let [b, tb] = lines[1].trim().split(/\s+/).map(Number);
    let [h, m] = lines[2].trim().split(':').map(Number);

    let x, y, w = 0, z = 300;
    x = 60 * h + m;
    y = 60 * h + m + ta;

    while (true) {
        if (z + tb < x) {
            z = z + b;
            continue;
        } else if (z + tb > x && z < y && z < 1440) {
            w += 1;
            z = z + b;
            continue;
        } else if (z > y) {
            break;
        } else if (z + tb === x || z === y) {
            z = z + b;
            continue;
        }
    }

    console.log(w);
});
